update vm_tenant_label_type_config
set label_type_name = #{labelTypeName}, modifier = #{modifier}, update_time=NOW()
where id = #{id}

update vm_tenant_label_type_config
set delete_flag = 1, modifier = #{modifier}, update_time=NOW()
where id = #{id}

mapper.select:
