FROM vm_tenant_label_type_config
where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0 and label_type_name = #{labelTypeName}

    and id != #{id}

SELECT count(*)
FROM vm_tenant_label_config
